package dev.pocketengine.features.local.project;

import static org.junit.Assert.*;
import java.util.*;
import org.json.*;
import org.junit.Test;

public final class ProjectByteCopyTest {
    private static final byte[] SOURCE={0,(byte)255,65,10};
    private static JSONObject edit()throws Exception{return new JSONObject().put("path","assets/copied.bin").put("action","copy_bytes").put("fromPath","original.bin").put("expectedHash","absent").put("expectedSourceHash",ProjectSources.sha256(SOURCE));}
    private static JSONObject snapshot(Map<String,byte[]> files)throws Exception{JSONArray rows=new JSONArray();for(var file:new TreeMap<>(files).entrySet())rows.put(new JSONObject().put("path",file.getKey()).put("binary",true).put("contentBase64",Base64.getEncoder().encodeToString(file.getValue())).put("sha256",ProjectSources.sha256(file.getValue())));return new JSONObject().put("checkout",new JSONObject().put("id","11111111-1111-1111-1111-111111111111").put("projectId","22222222-2222-2222-2222-222222222222")).put("files",rows);}
    private static JSONObject row()throws Exception{return ProjectExactPatch.prepare(snapshot(Map.of("original.bin",SOURCE)),new JSONArray().put(edit())).getJSONObject(0);}
    private static JSONObject plan(JSONObject file,Map<String,byte[]> actual,String operation)throws Exception{JSONObject source=ProjectSources.describe(snapshot(actual));boolean inverse=operation!=null;JSONObject payload=new JSONObject().put("checkoutId",source.getString("checkoutId")).put("expectedSourceDigest",source.getString("sourceDigest")).put("files",new JSONArray().put(file));if(inverse)payload.put("revertsOperationId",operation);JSONObject step=new JSONObject().put("id",inverse?"revert_operation":"patch").put("label","Original exact source byte copy").put("localCommand","patchFiles").put("effects",new JSONObject().put("writes",true).put("runtime","app_private_checkout")).put("payload",payload);return ProjectBuildPlan.seal(new JSONObject().put("format","pocketworld.project-plan.v1").put("projectId",source.getString("projectId")).put("checkoutId",source.getString("checkoutId")).put("sourceDigest",source.getString("sourceDigest")).put("sourceManifest",source.getJSONArray("files")).put("runtimeId","termux").put("intent",inverse?"revert_operation":"patch").put("available",true).put("warnings",new JSONArray()).put("steps",new JSONArray().put(step)));}
    private static JSONObject receipt(JSONObject file)throws Exception{return new JSONObject().put("receiptReceived",true).put("status","completed").put("files",new JSONArray().put(new JSONObject().put("path",file.getString("path")).put("state","applied").put("afterHash",file.getString("afterHash")).put("actualAfterHash",file.getString("afterHash"))));}
    @Test public void exactOriginalBinaryBytesAreFrozenAsANewFileAndBindToTheActualSourceManifest()throws Exception{JSONObject row=row();assertEquals("create",row.getString("action"));assertEquals("absent",row.getString("expectedHash"));assertArrayEquals(new byte[0],ProjectExactPatch.payloadBytes(row,true));assertArrayEquals(SOURCE,ProjectExactPatch.payloadBytes(row,false));assertEquals(ProjectSources.sha256(SOURCE),row.getString("afterHash"));assertEquals("original.bin",row.getJSONObject("copiedFrom").getString("path"));ProjectBuildPlan.verified(plan(row,Map.of("original.bin",SOURCE),null));assertArrayEquals(SOURCE,new byte[]{0,(byte)255,65,10});}
    @Test public void existingOrSameTargetWrongSourceAndModelProvidedBodiesAreRejectedBeforePreparing()throws Exception{for(String field:new String[]{"content","replacements","contentBase64","beforeContentBase64","newHex","expectedHex","byteOffset"})assertThrows(Exception.class,()->ProjectByteCopy.prepare("assets/copied.bin",Map.of("original.bin",SOURCE),edit().put(field,"not actual source")));assertThrows(SecurityException.class,()->ProjectByteCopy.prepare("assets/copied.bin",Map.of("original.bin",SOURCE,"assets/copied.bin",SOURCE),edit()));assertThrows(SecurityException.class,()->ProjectByteCopy.prepare("original.bin",Map.of("original.bin",SOURCE),edit()));assertThrows(SecurityException.class,()->ProjectByteCopy.prepare("assets/copied.bin",Map.of("original.bin",SOURCE),edit().put("expectedSourceHash","0".repeat(64))));assertThrows(SecurityException.class,()->ProjectByteCopy.prepare("assets/copied.bin",Map.of("original.bin",SOURCE),edit().put("expectedHash",ProjectSources.sha256(SOURCE))));assertThrows(SecurityException.class,()->ProjectByteCopy.prepare("assets/copied.bin",Map.of(),edit()));}
    @Test public void sourceAndDestinationBoundsDoNotBecomeRecursiveOrDependencyFilesystemAccess()throws Exception{for(String path:new String[]{"../escape","/absolute","node_modules/secret.bin","build/output.bin"})assertThrows(Exception.class,()->ProjectByteCopy.prepare(path,Map.of("original.bin",SOURCE),edit()));assertThrows(Exception.class,()->ProjectByteCopy.prepare("copy.bin",Map.of("node_modules/secret.bin",SOURCE),edit().put("fromPath","node_modules/secret.bin")));byte[] large=new byte[262145];assertThrows(IllegalArgumentException.class,()->ProjectByteCopy.prepare("copy.bin",Map.of("original.bin",large),edit().put("expectedSourceHash",ProjectSources.sha256(large))));byte[] max=new byte[262144];JSONObject limit=ProjectByteCopy.prepare("copy.bin",Map.of("original.bin",max),edit().put("expectedSourceHash",ProjectSources.sha256(max)));assertEquals(max.length,ProjectByteCopy.validated(limit)[1].length);JSONObject empty=ProjectByteCopy.prepare("empty-copy",Map.of("original.bin",new byte[0]),edit().put("expectedSourceHash",ProjectSources.sha256(new byte[0])));assertEquals("create",empty.getString("action"));assertEquals(0,ProjectByteCopy.validated(empty)[1].length);}
    @Test public void recomputingAForgeDoesNotMakeModelChosenBytesComeFromAnUnchangedOriginalManifest()throws Exception{byte[] fake={7,7,7,7};String sha=ProjectSources.sha256(fake);JSONObject forged=row();forged.put("contentBase64",Base64.getEncoder().encodeToString(fake)).put("afterHash",sha);forged.getJSONObject("copiedFrom").put("sha256",sha);forged.getJSONArray("changes").getJSONObject(0).put("sourceHash",sha);assertArrayEquals(fake,ProjectByteCopy.validated(forged)[1]);assertThrows(SecurityException.class,()->ProjectBuildPlan.verified(plan(forged,Map.of("original.bin",SOURCE),null)));JSONObject absent=row();absent.getJSONObject("copiedFrom").put("path","not-in-source.bin");absent.getJSONArray("changes").getJSONObject(0).put("fromPath","not-in-source.bin");assertThrows(SecurityException.class,()->ProjectBuildPlan.verified(plan(absent,Map.of("original.bin",SOURCE),null)));assertThrows(SecurityException.class,()->ProjectBuildPlan.verified(plan(row(),Map.of("original.bin",SOURCE,"assets/copied.bin",new byte[0]),null)));JSONObject fractional=plan(row(),Map.of("original.bin",SOURCE),null);fractional.getJSONArray("sourceManifest").getJSONObject(0).put("bytes",4.5);fractional.remove("planId");fractional.remove("planDigest");assertThrows(SecurityException.class,()->ProjectBuildPlan.verified(ProjectBuildPlan.seal(fractional)));}
    @Test public void malformedOrMixedEncodedRowsCannotBecomeAnArbitraryReplacement()throws Exception{for(String field:new String[]{"action","encoding","copyDirection","expectedHash","afterHash","bytePatchContract"}){JSONObject value=row().put(field,"wrong");assertThrows(Exception.class,()->ProjectByteCopy.validated(value));}for(Object size:new Object[]{-1,1.5,"4",true,262145})assertThrows(Exception.class,()->ProjectByteCopy.validated(row().put("afterBytes",size)));assertThrows(Exception.class,()->ProjectByteCopy.validated(row().put("beforeContent","unrelated")));assertThrows(Exception.class,()->ProjectByteCopy.validated(row().put("contentBase64","AP9BCg")));JSONObject extra=row();extra.getJSONObject("copiedFrom").put("hostPath","/arbitrary");assertThrows(SecurityException.class,()->ProjectByteCopy.validated(extra));}
    @Test public void completeBodiesStayPrivateWhileNativeReviewRetainsTheExactCopySourceAndTarget()throws Exception{JSONObject plan=ProjectBuildPlan.verified(plan(row(),Map.of("original.bin",SOURCE),null)),review=ProjectPlanRecords.reviewStep(plan.getJSONArray("steps").getJSONObject(0));JSONObject file=review.getJSONObject("request").getJSONArray("files").getJSONObject(0);assertFalse(review.toString().contains("contentBase64"));assertFalse(review.toString().contains("ContentBase64"));assertEquals("original.bin",file.getJSONObject("copiedFrom").getString("path"));assertEquals("copy_bytes",file.getJSONArray("changes").getJSONObject(0).getString("kind"));JSONObject reference=ProjectPlanRecords.reference(UUID.randomUUID().toString(),plan);assertFalse(reference.toString().contains("contentBase64"));assertTrue(reference.getBoolean("fullPlanStoredInOriginalTaskStore"));assertThrows(IllegalArgumentException.class,()->ProjectPlanRecords.requireInline(new JSONObject().put("plan",plan).put("stepId","patch")));assertTrue(plan.toString().contains("contentBase64"));}
    @Test public void aNewReversalOnlyRemovesTheExactOriginalCopyAndDoesNotNeedTheSourceToRemainUnchanged()throws Exception{JSONObject original=row();String operation=UUID.randomUUID().toString();JSONObject current=snapshot(Map.of("original.bin",new byte[]{9},"assets/copied.bin",SOURCE));JSONObject reverse=ProjectExactPatch.reverse(current,new JSONArray().put(original),receipt(original),operation).getJSONObject(0);assertEquals("delete",reverse.getString("action"));assertEquals(operation,reverse.getString("revertsOperationId"));assertArrayEquals(SOURCE,ProjectExactPatch.payloadBytes(reverse,true));assertEquals(0,ProjectExactPatch.payloadBytes(reverse,false).length);assertEquals("absent",reverse.getString("afterHash"));ProjectBuildPlan.verified(plan(reverse,Map.of("original.bin",new byte[]{9},"assets/copied.bin",SOURCE),operation));assertThrows(SecurityException.class,()->ProjectByteCopy.reverse(reverse,UUID.randomUUID().toString()));assertThrows(SecurityException.class,()->ProjectBuildPlan.verified(plan(reverse,Map.of("original.bin",SOURCE),operation)));assertThrows(SecurityException.class,()->ProjectBuildPlan.verified(plan(reverse,Map.of("original.bin",SOURCE,"assets/copied.bin",SOURCE),UUID.randomUUID().toString())));}
    @Test public void unknownUnappliedOrChangedAfterBytesCannotAuthorizeAConditionalCopyRemoval()throws Exception{JSONObject original=row();JSONObject current=snapshot(Map.of("original.bin",SOURCE,"assets/copied.bin",SOURCE));assertThrows(SecurityException.class,()->ProjectExactPatch.reverse(current,new JSONArray().put(original),new JSONObject(receipt(original).toString()).put("status","unknown"),UUID.randomUUID().toString()));assertThrows(SecurityException.class,()->ProjectExactPatch.reverse(snapshot(Map.of("original.bin",SOURCE,"assets/copied.bin",new byte[]{9})),new JSONArray().put(original),receipt(original),UUID.randomUUID().toString()));JSONObject unapplied=receipt(original);unapplied.getJSONArray("files").getJSONObject(0).put("state","failed");assertThrows(SecurityException.class,()->ProjectExactPatch.reverse(current,new JSONArray().put(original),unapplied,UUID.randomUUID().toString()));}
}
